    <div class="products-list"><div class="table-wrap"><table class="products-table"><thead><tr><th class="image-col">تصویر</th><th>نام کالا</th><th>کد کالا</th><th>دسته‌بندی</th><th>تعداد تنوع</th><th>موجودی مرکزی</th><th>قیمت فروش</th><th>وضعیت فروش</th><th class="actions-col">عملیات</th></tr></thead><tbody id="productsBody"></tbody></table></div><div id="productsState" class="loading-row">در حال دریافت فهرست کالاها...</div><div id="productsSentinel" class="sentinel"></div></div>

