</div>

<script>
document.addEventListener('DOMContentLoaded',()=>{
const app=document.getElementById('productsApp'),body=document.getElementById('productsBody'),stateEl=document.getElementById('productsState'),sentinel=document.getElementById('productsSentinel'),categories=JSON.parse(app.dataset.categories||'[]'),productsUrl=app.dataset.productsUrl;let filters={limit:50,...JSON.parse(app.dataset.initialFilters||'{}')},items=new Map(),nextCursor=null,hasMore=true,isLoading=false,productRequestController=null,requestSeq=0,debounceTimer=null,activeActionsButton=null;const fa=n=>String(n??0).replace(/\d/g,d=>'۰۱۲۳۴۵۶۷۸۹'[d]),money=n=>Number(n||0)>0?fa(Number(n).toLocaleString('en-US'))+' ریال':'بدون قیمت',esc=s=>String(s??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
function fillCats(){const cat=document.getElementById('categoryFilter'),sub=document.getElementById('subcategoryFilter');cat.innerHTML='<option value="">همه دسته‌ها</option>'+categories.filter(c=>!c.parent_id).map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('');cat.value=filters.category_id||'';fillSub();sub.value=filters.subcategory_id||''}function fillSub(){const sub=document.getElementById('subcategoryFilter'),pid=Number(document.getElementById('categoryFilter').value||0),ids=new Set((categories.find(c=>c.id===pid)?.descendant_ids||[]).filter(id=>id!==pid));sub.innerHTML='<option value="">همه زیر‌دسته‌ها</option>'+categories.filter(c=>ids.has(c.id)).map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('');sub.disabled=!pid}function readFilters(){filters.q=document.getElementById('productSearch').value.trim();filters.category_id=document.getElementById('categoryFilter').value;filters.subcategory_id=document.getElementById('subcategoryFilter').value;filters.stock_status=document.getElementById('stockFilter').value;filters.sellable_status=document.getElementById('sellableFilter').value;filters.min_price=document.getElementById('minPrice').value.trim();filters.max_price=document.getElementById('maxPrice').value.trim();filters.has_variants=document.getElementById('hasVariants').value;filters.without_price=document.getElementById('withoutPrice').value;filters.sort=document.getElementById('sortFilter').value;filters.direction=document.getElementById('directionFilter').value}function setControls(){document.getElementById('productSearch').value=filters.q||'';['stock_status:stockFilter','sellable_status:sellableFilter','min_price:minPrice','max_price:maxPrice','has_variants:hasVariants','without_price:withoutPrice','sort:sortFilter','direction:directionFilter'].forEach(x=>{let[k,id]=x.split(':');document.getElementById(id).value=filters[k]||''})}function updateUrl(){const p=new URLSearchParams();Object.entries(filters).forEach(([k,v])=>{if(v&&k!=='limit')p.set(k,v)});history.replaceState({},'',location.pathname+(p.toString()?'?'+p:''))}function resetList(){closeActionsMenu();items.clear();nextCursor=null;hasMore=true;body.innerHTML='';loadProducts(true)}function buildUrl(cursor){const u=new URL(productsUrl,location.origin);Object.entries(filters).forEach(([k,v])=>{if(v!==undefined&&v!==null&&v!=='')u.searchParams.set(k,v)});u.searchParams.set('limit',filters.limit||50);if(cursor)u.searchParams.set('cursor',cursor);return u}async function loadProducts(reset=false){if(isLoading||(!hasMore&&!reset))return;closeActionsMenu();isLoading=true;const seq=++requestSeq;if(reset&&productRequestController)productRequestController.abort();productRequestController=new AbortController();stateEl.className='loading-row';stateEl.textContent=items.size?'در حال دریافت موارد بیشتر...':'در حال دریافت فهرست کالاها...';document.getElementById('searchWrap').classList.add('is-searching');try{const r=await fetch(buildUrl(reset?null:nextCursor),{headers:{Accept:'application/json','X-Requested-With':'XMLHttpRequest'},signal:productRequestController.signal});const j=await r.json();if(seq!==requestSeq)return;if(!r.ok)throw new Error();(j.data||[]).forEach(p=>{if(!items.has(p.id)){items.set(p.id,p);body.insertAdjacentHTML('beforeend',productRow(p))}});nextCursor=j.meta?.next_cursor||null;hasMore=!!j.meta?.has_more;stateEl.textContent=items.size?(hasMore?'':'همه کالاها نمایش داده شدند.'):emptyText();stateEl.className=items.size?'end-state':'empty-state'}catch(e){if(e.name!=='AbortError'){stateEl.textContent='دریافت فهرست کالاها با خطا مواجه شد. تلاش مجدد';stateEl.className='empty-state'}}finally{if(seq===requestSeq){isLoading=false;document.getElementById('searchWrap').classList.remove('is-searching')}}}function emptyText(){return filters.category_id||filters.subcategory_id?'در این دسته‌بندی کالایی وجود ندارد.':'کالایی با این مشخصات پیدا نشد.'}
function productRow(p){const price=p.min_price&&p.max_price&&p.min_price!==p.max_price?`از ${money(p.min_price)} تا ${money(p.max_price)}`:money(p.max_price||p.min_price),returnTo=encodeURIComponent(location.href);return `<tr data-product-id="${p.id}"><td class="image-col"><span class="desktop-label">تصویر:</span><span class="product-thumb">${p.image_url?`<img src="${esc(p.image_url)}" alt="">`:'📷'}</span></td><td><span class="desktop-label">نام:</span><strong>${esc(p.name)}</strong><div class="muted">رزرو: ${fa(p.reserved)}</div></td><td><span class="desktop-label">کد:</span><span class="mono pill pill-gray">${esc(p.short_code||'—')}</span></td><td><span class="desktop-label">دسته:</span>${esc(p.category_path||p.category||'—')}</td><td><span class="desktop-label">تنوع:</span>${fa(p.variants_count)}</td><td><span class="desktop-label">موجودی:</span><span class="pill ${p.total_stock>0?'pill-green':'pill-red'}">${fa(p.total_stock)}</span></td><td><span class="desktop-label">قیمت:</span><span class="price">${price}</span></td><td><span class="desktop-label">فروش:</span><span class="pill ${p.sales_enabled?'pill-green':'pill-gray'}">${p.sales_enabled?'قابل فروش':'غیرفعال'}</span></td><td class="actions-col"><button class="action-btn" type="button" data-product-actions data-id="${p.id}" data-edit="${esc(p.routes.edit)}?return_to=${returnTo}" data-stock="${esc(p.routes.stock)}" data-sales-ledger="${esc(p.routes.sales_ledger)}" data-purchase-ledger="${esc(p.routes.purchase_ledger)}" data-deactivate="${esc(p.routes.deactivate)}" aria-expanded="false">عملیات <span class="action-caret">▾</span></button></td></tr>`}
function schedule(){closeActionsMenu();clearTimeout(debounceTimer);readFilters();const q=filters.q||'';if(q&&!/^\d+$/.test(q)&&q.length<2)return;debounceTimer=setTimeout(()=>{updateUrl();resetList()},300)}
function menuHtml(btn){return `<ul><li><button class="product-action-item" type="button" data-action="variants" data-id="${btn.dataset.id}">مشاهده تنوع‌ها</button></li><li><a class="product-action-item" href="${btn.dataset.edit}">ویرایش کالا</a></li><li><a class="product-action-item" href="${btn.dataset.stock}">موجودی انبار</a></li><li><a class="product-action-item" href="${btn.dataset.salesLedger}">کارتکس فروش</a></li><li><a class="product-action-item" href="${btn.dataset.purchaseLedger}">کارتکس خرید</a></li><li class="divider"><a class="product-action-item danger" href="${btn.dataset.deactivate}">غیرفعال‌سازی فروش</a></li></ul>`}
function closeActionsMenu(){const m=document.getElementById('productActionsMenu');if(m)m.remove();if(activeActionsButton){activeActionsButton.setAttribute('aria-expanded','false');activeActionsButton=null}}
function positionActionsMenu(menu,btn){if(matchMedia('(max-width:800px)').matches)return;const r=btn.getBoundingClientRect(),pad=8;menu.style.display='block';const mw=Math.min(260,Math.max(220,menu.offsetWidth)),mh=menu.offsetHeight;let top=(innerHeight-r.bottom-pad>=mh||r.top< mh+pad)?r.bottom+pad:r.top-mh-pad;let left=r.right-mw;left=Math.max(pad,Math.min(left,innerWidth-mw-pad));top=Math.max(pad,Math.min(top,innerHeight-mh-pad));menu.style.left=left+'px';menu.style.top=top+'px'}
function openActionsMenu(btn){if(activeActionsButton===btn){closeActionsMenu();return}closeActionsMenu();const menu=document.createElement('div');menu.id='productActionsMenu';menu.className='product-actions-menu';menu.innerHTML=menuHtml(btn);document.body.appendChild(menu);activeActionsButton=btn;btn.setAttribute('aria-expanded','true');positionActionsMenu(menu,btn);requestAnimationFrame(()=>menu.classList.add('is-open'))}
body.addEventListener('click',e=>{const btn=e.target.closest('[data-product-actions]');if(btn){e.preventDefault();e.stopPropagation();openActionsMenu(btn)}});
document.addEventListener('click',e=>{const menu=document.getElementById('productActionsMenu');if(!menu)return;if(e.target.closest('#productActionsMenu')){if(e.target.closest('a,.product-action-item'))closeActionsMenu();return}if(!e.target.closest('[data-product-actions]'))closeActionsMenu()});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeActionsMenu()});window.addEventListener('scroll',closeActionsMenu,{passive:true});window.addEventListener('resize',closeActionsMenu);
document.getElementById('moreFiltersBtn').onclick=()=>{closeActionsMenu();document.getElementById('moreFilters').classList.toggle('is-open')};['productSearch','stockFilter','sellableFilter','hasVariants','withoutPrice','sortFilter','directionFilter'].forEach(id=>document.getElementById(id).addEventListener('input',schedule));['minPrice','maxPrice'].forEach(id=>document.getElementById(id).addEventListener('change',schedule));document.getElementById('categoryFilter').addEventListener('change',()=>{document.getElementById('subcategoryFilter').value='';fillSub();schedule()});document.getElementById('subcategoryFilter').addEventListener('change',schedule);new IntersectionObserver(es=>{if(es.some(e=>e.isIntersecting))loadProducts(false)},{rootMargin:'350px'}).observe(sentinel);
let variant={productId:null,next:null,hasMore:false,loading:false,controller:null,seq:0};const drawer=document.getElementById('variantDrawer'),vList=document.getElementById('variantsList'),vState=document.getElementById('variantsState');function openVariants(id){closeActionsMenu();variant={productId:id,next:null,hasMore:true,loading:false,controller:null,seq:0};vList.innerHTML='';drawer.classList.add('is-open');drawer.setAttribute('aria-hidden','false');loadVariants(true)}document.addEventListener('click',e=>{const b=e.target.closest('[data-action="variants"]');if(b){e.preventDefault();openVariants(b.dataset.id)}});document.querySelectorAll('[data-drawer-close]').forEach(x=>x.onclick=()=>{drawer.classList.remove('is-open');drawer.setAttribute('aria-hidden','true');if(variant.controller)variant.controller.abort()});['variantSearch','variantStock','variantSellable'].forEach(id=>document.getElementById(id).addEventListener('input',()=>{clearTimeout(debounceTimer);debounceTimer=setTimeout(()=>{variant.next=null;variant.hasMore=true;vList.innerHTML='';loadVariants(true)},300)}));async function loadVariants(reset=false){if(variant.loading||!variant.hasMore)return;variant.loading=true;if(reset&&variant.controller)variant.controller.abort();variant.controller=new AbortController();const seq=++variant.seq;vState.textContent='در حال دریافت تنوع‌ها...';try{const u=new URL(`/products/${variant.productId}/variants`,location.origin);u.searchParams.set('limit',50);if(variant.next&&!reset)u.searchParams.set('cursor',variant.next);[['q','variantSearch'],['stock_status','variantStock'],['sellable_status','variantSellable']].forEach(([k,id])=>{const val=document.getElementById(id).value;if(val)u.searchParams.set(k,val)});const r=await fetch(u,{headers:{Accept:'application/json','X-Requested-With':'XMLHttpRequest'},signal:variant.controller.signal});const j=await r.json();if(seq!==variant.seq)return;document.getElementById('drawerTitle').textContent=j.product?.name||'تنوع‌های کالا';document.getElementById('drawerSubTitle').textContent='کد کالا: '+(j.product?.short_code||'—');(j.data||[]).forEach(v=>vList.insertAdjacentHTML('beforeend',variantRow(v)));variant.next=j.meta?.next_cursor||null;variant.hasMore=!!j.meta?.has_more;vState.textContent=vList.children.length?(variant.hasMore?'':'همه تنوع‌ها نمایش داده شدند.'):'برای این کالا تنوعی ثبت نشده است.'}catch(e){if(e.name!=='AbortError')vState.textContent='دریافت تنوع‌ها با خطا مواجه شد.'}finally{if(seq===variant.seq)variant.loading=false}}function variantRow(v){return `<div class="variant-row"><div class="d-flex justify-content-between gap-2"><strong>${esc(v.name||'—')}</strong><span class="pill ${v.sales_enabled?'pill-green':'pill-gray'}">${v.sales_enabled?'قابل فروش':'غیرفعال'}</span></div><div class="muted mono">${esc(v.sku||v.barcode||'—')}</div><div class="d-flex flex-wrap gap-2 mt-2"><span class="pill ${v.stock>0?'pill-green':'pill-red'}">موجودی: ${fa(v.stock)}</span><span class="pill pill-yellow">رزرو: ${fa(v.reserved)}</span><span class="price">${money(v.sell_price)}</span></div><div class="mt-2 d-flex flex-wrap gap-2"><a class="btn btn-outline-primary btn-sm" href="${esc(v.routes.edit)}?return_to=${encodeURIComponent(location.href)}">ویرایش</a><a class="btn btn-outline-secondary btn-sm" href="${esc(v.routes.stock)}">موجودی انبار</a><a class="btn btn-outline-secondary btn-sm" href="${esc(v.routes.sales_ledger)}">کارتکس فروش</a><a class="btn btn-outline-secondary btn-sm" href="${esc(v.routes.purchase_ledger)}">کارتکس خرید</a><a class="btn btn-outline-danger btn-sm" href="${esc(v.routes.deactivate)}">غیرفعال‌سازی</a></div></div>`}new IntersectionObserver(es=>{if(drawer.classList.contains('is-open')&&es.some(e=>e.isIntersecting))loadVariants(false)},{rootMargin:'250px'}).observe(document.getElementById('variantsSentinel'));fillCats();setControls();resetList();});
</script>
@endsection
